INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.62.1',
  '2026-08-03',
  'AI — агент больше не теряет codex: поиск бинарника не только в PATH',
  E'Задача для Codex падала с ошибкой «codex не найден в PATH», хотя инструмент установлен. Теперь агент ищет инструменты не только в PATH, но и в стандартных местах установки, а найденный путь показывается в карточке инструмента на странице AI. Если инструмент лежит совсем нестандартно, путь можно указать вручную в настройках агента на машине.',
  E'Причина: агент запускается как systemd user-сервис, а systemd даёт процессу минимальный PATH (без ~/.local/bin и без nvm) — exec.LookPath промахивался, хотя в логин-шелле команда находилась.\n\nНовый резолвер ai-agent/binpath.go (агент v1.7.0). Порядок: AI_AGENT_CLAUDE/AI_AGENT_CODEX (полный путь) → PATH → стандартные каталоги: nvm/fnm/volta/nodenv (версии сортируются численно, берётся самая свежая — на машине рядом лежали node v16 и v20), ~/.local/bin, ~/bin, npm-global, yarn/pnpm/bun/deno/cargo/asdf, /usr/local/bin, /opt/homebrew/bin, /usr/bin, /snap/bin. Успешный результат кэшируется с перепроверкой на существование (установка подхватывается без перезапуска агента), неуспешный — нет.\n\nВторая часть фикса: дочернему процессу PATH дополняется каталогом бинарника и каталогом цели симлинка — codex это JS-скрипт с shebang env node, и без этого подхватывался системный node v18 вместо v20, рядом с которым codex установлен. Все запуски инструментов переведены на toolCmd().\n\nВ toolStatus добавлено поле path (бэкенд хранит tools как JSON, изменений не потребовал), фронтенд показывает его в карточке инструмента. Сообщение об ошибке перечисляет, где искали, и подсказывает переменную окружения. 11 юнит-тестов: поиск свежей версии в nvm, ~/.local/bin, пропуск каталогов и неисполняемых файлов, переопределение переменной (и битый путь в ней), текст ошибки, разбор и сравнение версий, PATH для дочернего процесса (в т.ч. через симлинк), перепроверка кэша.'
);
